CREATE SEQUENCE GAME_REQUEST_CANDIDATE_SEQ INCREMENT BY 50;
CREATE SEQUENCE GAME_REQUEST_CANDIDATE_APPROVAL_SEQ INCREMENT BY 50;
CREATE TABLE GAME_REQUEST_CANDIDATE (ID BIGINT NOT NULL PRIMARY KEY, GAME_REQUEST_ID BIGINT NOT NULL, PROVIDER_LABEL CHARACTER VARYING(128) NOT NULL, DISPLAY_NAME CHARACTER VARYING(512) NOT NULL, EXTERNAL_REFERENCE CHARACTER VARYING(2048) NOT NULL, NOTES CHARACTER LARGE OBJECT, RECORDED_AT TIMESTAMP WITH TIME ZONE NOT NULL, RECORDED_BY CHARACTER VARYING(255) NOT NULL, SELECTED BOOLEAN NOT NULL, CONSTRAINT FK_REQUEST_CANDIDATE_REQUEST FOREIGN KEY (GAME_REQUEST_ID) REFERENCES GAME_REQUEST ON DELETE CASCADE);
CREATE TABLE GAME_REQUEST_CANDIDATE_APPROVAL (ID BIGINT NOT NULL PRIMARY KEY, CANDIDATE_ID BIGINT NOT NULL, APPROVED_AT TIMESTAMP WITH TIME ZONE NOT NULL, APPROVED_BY CHARACTER VARYING(255) NOT NULL, REASON CHARACTER LARGE OBJECT, CONSTRAINT FK_REQUEST_CANDIDATE_APPROVAL_CANDIDATE FOREIGN KEY (CANDIDATE_ID) REFERENCES GAME_REQUEST_CANDIDATE ON DELETE CASCADE);
